class ConnectGame:
    def __init__(self, board):
        self.board = [line.split() for line in board.splitlines() if line.strip()]

    def get_winner(self):
        if self._connects("X"):
            return "X"
        if self._connects("O"):
            return "O"
        return ""

    def _connects(self, player):
        rows = self.board
        n = len(rows)
        if n == 0:
            return False
        m = len(rows[0])

        if player == "X":
            # X plays from left to right.
            start = [(r, 0) for r in range(n) if rows[r][0] == player]
            reached = lambda r, c: c == m - 1
        else:
            # O plays from top to bottom.
            start = [(0, c) for c in range(m) if rows[0][c] == player]
            reached = lambda r, c: r == n - 1

        visited = set(start)
        queue = list(start)
        # Hex neighbors in this skewed coordinate system.
        neighbors = ((0, -1), (0, 1), (-1, 0), (-1, 1), (1, -1), (1, 0))
        while queue:
            r, c = queue.pop()
            if reached(r, c):
                return True
            for dr, dc in neighbors:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m:
                    if (nr, nc) not in visited and rows[nr][nc] == player:
                        visited.add((nr, nc))
                        queue.append((nr, nc))
        return False

